/* Generated from atelier.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='atelier'],
[data-ui-theme='atelier'] {
  color-scheme: light;
  --ui-background: oklch(0.974 0.025 62);
  --ui-foreground: oklch(0.21 0.045 25);
  --ui-card: oklch(0.995 0.008 62);
  --ui-card-foreground: oklch(0.21 0.045 25);
  --ui-popover: oklch(0.995 0.008 62);
  --ui-popover-foreground: oklch(0.21 0.045 25);
  --ui-primary: oklch(0.52 0.2 28);
  --ui-primary-foreground: oklch(0.98 0.01 62);
  --ui-secondary: oklch(0.9 0.07 72);
  --ui-secondary-foreground: oklch(0.25 0.05 25);
  --ui-muted: oklch(0.97 0.025 62);
  --ui-muted-foreground: oklch(0.49 0.06 35);
  --ui-accent: oklch(0.82 0.16 115);
  --ui-accent-foreground: oklch(0.24 0.055 120);
  --ui-destructive: oklch(0.45 0.2 20);
  --ui-destructive-foreground: oklch(0.98 0 0);
  --ui-border: oklch(0.77 0.07 62);
  --ui-input: oklch(0.8 0.06 62);
  --ui-ring: oklch(0.6 0.2 28);
  --ui-chart-1: oklch(0.6 0.22 28);
  --ui-chart-2: oklch(0.7 0.18 115);
  --ui-chart-3: oklch(0.62 0.17 245);
  --ui-chart-4: oklch(0.73 0.17 72);
  --ui-chart-5: oklch(0.58 0.18 330);
  --ui-radius: 1rem;
  --ui-radius-panel: 1.5rem;
  --ui-control-height: 2.5rem;
  --ui-control-height-sm: 2.15rem;
  --ui-control-height-lg: 2.8rem;
  --ui-font-body: 'Aptos', 'Gill Sans', ui-sans-serif, sans-serif;
  --ui-font-heading: 'Cooper Black', 'Iowan Old Style', ui-serif, serif;
  --ui-shadow-control: 0 2px 0 oklch(0.21 0.045 25 / 0.14);
  --ui-shadow-panel: 0 24px 0 -12px oklch(0.58 0.22 28 / 0.22);
  --ui-motion-fast: 150ms;
  --ui-motion-standard: 240ms;
}

:root.dark,
[data-ui-preset='atelier'].dark,
[data-ui-theme='atelier'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.16 0.04 25);
  --ui-foreground: oklch(0.94 0.025 62);
  --ui-card: oklch(0.21 0.05 25);
  --ui-card-foreground: oklch(0.94 0.025 62);
  --ui-popover: oklch(0.2 0.05 25);
  --ui-popover-foreground: oklch(0.94 0.025 62);
  --ui-primary: oklch(0.72 0.19 32);
  --ui-primary-foreground: oklch(0.17 0.04 25);
  --ui-secondary: oklch(0.31 0.07 35);
  --ui-secondary-foreground: oklch(0.94 0.025 62);
  --ui-muted: oklch(0.28 0.055 30);
  --ui-muted-foreground: oklch(0.7 0.05 62);
  --ui-accent: oklch(0.65 0.15 115);
  --ui-accent-foreground: oklch(0.17 0.04 25);
  --ui-destructive: oklch(0.79 0.17 20);
  --ui-destructive-foreground: oklch(0.98 0 0);
  --ui-border: oklch(0.38 0.08 35);
  --ui-input: oklch(0.35 0.07 35);
  --ui-ring: oklch(0.72 0.18 32);
  --ui-chart-1: oklch(0.72 0.19 32);
  --ui-chart-2: oklch(0.7 0.16 115);
  --ui-chart-3: oklch(0.7 0.15 245);
  --ui-chart-4: oklch(0.76 0.16 72);
  --ui-chart-5: oklch(0.68 0.16 330);
  --ui-radius: 1rem;
  --ui-radius-panel: 1.5rem;
  --ui-control-height: 2.5rem;
  --ui-control-height-sm: 2.15rem;
  --ui-control-height-lg: 2.8rem;
  --ui-font-body: 'Aptos', 'Gill Sans', ui-sans-serif, sans-serif;
  --ui-font-heading: 'Cooper Black', 'Iowan Old Style', ui-serif, serif;
  --ui-shadow-control: 0 2px 0 oklch(0.21 0.045 25 / 0.14);
  --ui-shadow-panel: 0 24px 0 -12px oklch(0.58 0.22 28 / 0.22);
  --ui-motion-fast: 150ms;
  --ui-motion-standard: 240ms;
}
